'use strict';

const history = new Map();

function getSessionKey() {
  return process.env.CLAUDE_SESSION_ID || process.ppid || 'default';
}

function getHistory() {
  const key = getSessionKey();
  if (!history.has(key)) {
    history.set(key, { iterations: [], startedAt: Date.now() });
  }
  return history.get(key);
}

function recordIteration(gaps) {
  const h = getHistory();
  h.iterations.push({
    timestamp: Date.now(),
    gapIds: gaps.map(g => g.id),
    counts: {
      critical: gaps.filter(g => g.severity === 'critical').length,
      major: gaps.filter(g => g.severity === 'major').length,
      minor: gaps.filter(g => g.severity === 'minor').length
    }
  });
}

function getIterationCount() {
  return getHistory().iterations.length;
}

function getLastGapIds() {
  const iters = getHistory().iterations;
  if (iters.length === 0) return [];
  return iters[iters.length - 1].gapIds;
}

function getPreviousGapIds() {
  const iters = getHistory().iterations;
  if (iters.length < 2) return [];
  return iters[iters.length - 2].gapIds;
}

function reset() {
  history.delete(getSessionKey());
}

module.exports = { recordIteration, getHistory, getIterationCount, getLastGapIds, getPreviousGapIds, reset };

'use strict';

const { getIterationCount, getLastGapIds, getPreviousGapIds } = require('./audit-history.cjs');

const MAX_ITERATIONS = 5;
const STAGNATION_THRESHOLD = 2;

function shouldPass(currentGaps) {
  const iterCount = getIterationCount();
  const actionable = currentGaps.filter(g => g.severity === 'critical' || g.severity === 'major');

  if (actionable.length === 0) {
    return { pass: true, reason: 'no_actionable_gaps', unfillable: [] };
  }

  if (iterCount >= MAX_ITERATIONS) {
    return { pass: true, reason: 'max_iterations', unfillable: actionable.map(g => g.id) };
  }

  const currentIds = currentGaps.map(g => g.id);
  const lastIds = getLastGapIds();
  const prevIds = getPreviousGapIds();

  // Stagnation: gaps not decreasing for 2 consecutive iterations
  if (lastIds.length > 0 && currentIds.length >= lastIds.length) {
    if (prevIds.length > 0 && lastIds.length >= prevIds.length) {
      return { pass: true, reason: 'stagnating', unfillable: currentIds };
    }
  }

  // Repeat detection: same gap in 2+ iterations
  const unfillable = [];
  for (const gap of actionable) {
    if (lastIds.includes(gap.id)) {
      unfillable.push(gap.id);
    }
  }

  // If ALL actionable gaps are unfillable, pass
  if (unfillable.length > 0 && unfillable.length >= actionable.length) {
    return { pass: true, reason: 'all_unfillable', unfillable };
  }

  // Filter out unfillable from blocking set
  const stillBlocking = actionable.filter(g => !unfillable.includes(g.id));
  if (stillBlocking.length === 0) {
    return { pass: true, reason: 'only_unfillable_remain', unfillable };
  }

  return { pass: false, reason: null, unfillable };
}

module.exports = { shouldPass, MAX_ITERATIONS };

'use strict';

function classifyGaps(failedChecks) {
  const result = { critical: [], major: [], minor: [] };

  for (const check of failedChecks) {
    const severity = check.severity || 'minor';
    const gap = {
      id: check.id,
      severity,
      dimension: check.dimension || 'unknown',
      description: check.description || `Failed check: ${check.id}`,
      fix: check.fix || null
    };

    if (severity === 'critical') result.critical.push(gap);
    else if (severity === 'major') result.major.push(gap);
    else result.minor.push(gap);
  }

  return result;
}

function getAllActionable(classified) {
  return [...classified.critical, ...classified.major];
}

module.exports = { classifyGaps, getAllActionable };

