2	
3	const fs = require('fs');
4	const path = require('path');
5	const { classifyGaps, getAllActionable } = require('./gap-classifier.cjs');
6	const { shouldPass } = require('./convergence-detector.cjs');
7	const { recordIteration, getIterationCount } = require('./audit-history.cjs');
8	
9	const SCHEMAS_DIR = path.join(__dirname, 'audit-schemas');
10	const schemaCache = new Map();
11	
12	function loadSchema(type) {
13	  if (schemaCache.has(type)) return schemaCache.get(type);
14	  const filePath = path.join(SCHEMAS_DIR, `${type}.json`);
15	  if (!fs.existsSync(filePath)) return null;
16	  const schema = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
17	  schemaCache.set(type, schema);
18	  return schema;
19	}
20	
21	function loadAllSchemas() {
22	  const files = fs.readdirSync(SCHEMAS_DIR).filter(f => f.endsWith('.json') && !f.startsWith('_'));
23	  for (const f of files) {
24	    const type = f.replace('.json', '');
25	    if (!schemaCache.has(type)) loadSchema(type);
26	  }
27	  return [...schemaCache.values()];
28	}
29	
30	function detectType(text) {
31	  const schemas = loadAllSchemas();
32	  let bestMatch = null;
33	  let bestScore = 0;
34	
35	  for (const schema of schemas) {
36	    if (schema.type === 'default') continue;
37	    const patterns = schema.trigger_patterns || [];
38	    let score = 0;
39	    for (const p of patterns) {
40	      if (text.toLowerCase().includes(p.toLowerCase())) score++;
41	    }
42	    if (score > bestScore) {
43	      bestScore = score;
44	      bestMatch = schema.type;
45	    }
46	  }
47	
48	  return bestScore > 0 ? bestMatch : 'default';
49	}
50	
51	// Rule evaluation functions
52	const ruleFunctions = {
53	  min_length(text, arg) {
54	    const num = parseInt(arg, 10);
55	    return text.length >= num;
56	  },
57	
58	  contains(text, patterns) {
59	    const parts = patterns.split('|');
60	    return parts.some(p => new RegExp(p.trim(), 'i').test(text));
61	  },
62	
63	  not_contains(text, patterns) {
64	    const parts = patterns.split('|');
65	    return !parts.some(p => new RegExp(`\\b${p.trim()}\\b`, 'i').test(text));
66	  },
67	
68	  section_exists(text, patterns) {
69	    const parts = patterns.split('|');
70	    return parts.some(p => {
71	      const escaped = p.trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
72	      return new RegExp(`(^|\\n)\\s*#+\\s*.*${escaped}|\\*\\*.*${escaped}`, 'im').test(text);
73	    });
74	  },
75	
76	  count_pattern(text, patterns) {
77	    const parts = patterns.split('|');
78	    let count = 0;
79	    for (const p of parts) {
